#include "nv_pp512_flash_phase2_fp16_reference.cu"
#include <cuda_runtime.h>
#include <cstdio>
#include <vector>
#include <fstream>
#include <cmath>
int main(int ac,char**av){if(ac!=2)return 2;const char*d=av[1];constexpr int D=128,S=512,H=32,K=8,N=H*S*D;std::vector<half>q(N),kv(2*K*S*D);std::ifstream fq(std::string(d)+"/q.bin",std::ios::binary),fk(std::string(d)+"/k.bin",std::ios::binary),fv(std::string(d)+"/v.bin",std::ios::binary);fq.read((char*)q.data(),q.size()*2);fk.read((char*)kv.data(),K*S*D*2);fv.read((char*)kv.data()+K*S*D*2,K*S*D*2);std::vector<float>ref(N);std::ifstream fe(std::string(d)+"/expected.bin",std::ios::binary);fe.read((char*)ref.data(),ref.size()*4);half*dq,*dkv;float*do_;cudaMalloc(&dq,N*2);cudaMalloc(&dkv,kv.size()*2);cudaMalloc(&do_,(N+16)*4);cudaMemcpy(dq,q.data(),N*2,cudaMemcpyHostToDevice);cudaMemcpy(dkv,kv.data(),kv.size()*2,cudaMemcpyHostToDevice);cudaMemset(do_,0,(N+16)*4);auto launch=[&](){nv_pp512_flash_phase2_fp16_reference<<<dim3(S,H,1),dim3(32,4,1)>>>(dq,dkv,do_,0,S,S);};launch();if(cudaDeviceSynchronize()!=cudaSuccess)return 3;cudaEvent_t a,b;cudaEventCreate(&a);cudaEventCreate(&b);for(int i=0;i<5;i++)launch();cudaEventRecord(a);for(int i=0;i<20;i++)launch();cudaEventRecord(b);cudaEventSynchronize(b);float ms;cudaEventElapsedTime(&ms,a,b);std::vector<float>got(N+16);cudaMemcpy(got.data(),do_,(N+16)*4,cudaMemcpyDeviceToHost);double mx=0,mean=0;size_t bad=0;for(int i=0;i<N;i++){double e=fabs((double)got[i]-ref[i]);mx=fmax(mx,e);mean+=e;bad+=e>1e-4;}double c=0;for(int i=0;i<N;i++)c+=got[i]*(i%17+1);bool guard=true;for(int i=N;i<N+16;i++)guard&=got[i]==0;printf("launch_us=%.3f max_abs=%.9g mean_abs=%.9g mismatches=%zu checksum=%.9e canary=%s allclose=%s\n",ms*1000/20,mx,mean/N,bad,c,guard?"pass":"FAIL",(mx<=1e-4)?"pass":"FAIL");return (guard&&mx<=1e-4&&std::isfinite(c))?0:4;}
